import{_ as a,o as s,c as n,ag as l}from"./chunks/framework.CmaAMB6e.js";const c=JSON.parse('{"title":"系统设计学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/learning-path.md","filePath":"system-design/learning-path.md","lastUpdated":null}'),r={name:"system-design/learning-path.md"};function e(i,t,o,d,g,p){return s(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="系统设计学习路径" tabindex="-1">系统设计学习路径 <a class="header-anchor" href="#系统设计学习路径" aria-label="Permalink to &quot;系统设计学习路径&quot;">​</a></h1><blockquote><p>系统设计专属的概念序列与阶段划分。每个概念自成闭环,不与其他技能绑定。系统设计是后端资深/专家（L4/L5）考核的核心能力——从「会写接口」到「能设计整个系统」的分水岭。</p><p><strong>定位说明</strong>：使用者是前端工程师转后端。本线建立在已掌握的后端语言（Python/Java/Node.js）与数据库/Linux 基础之上,训练「架构思维」：容量估算、组件选型、高可用设计、经典案例演练。</p></blockquote><h2 id="学习策略" tabindex="-1">学习策略 <a class="header-anchor" href="#学习策略" aria-label="Permalink to &quot;学习策略&quot;">​</a></h2><ul><li><strong>概念驱动</strong>:按概念顺序推进,每个概念是一篇完整教程</li><li><strong>前端对照</strong>:每篇末尾有「前端对照」小节,用前端架构概念（组件化/状态管理/性能优化）帮助理解</li><li><strong>边学边练</strong>:每篇配练习建议,可用 <code>/practice system-design &lt;概念&gt;</code> 生成针对性练习</li></ul><h2 id="阶段总览" tabindex="-1">阶段总览 <a class="header-anchor" href="#阶段总览" aria-label="Permalink to &quot;阶段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>主题</th><th>概念数</th></tr></thead><tbody><tr><td>1</td><td>方法论</td><td>4</td></tr><tr><td>2</td><td>基础组件</td><td>5</td></tr><tr><td>3</td><td>高可用设计</td><td>5</td></tr><tr><td>4</td><td>经典案例</td><td>5</td></tr><tr><td>5</td><td>资深架构</td><td>7</td></tr><tr><td>6</td><td>综合实战</td><td>1</td></tr></tbody></table><hr><h2 id="阶段-1-·-方法论" tabindex="-1">阶段 1 · 方法论 <a class="header-anchor" href="#阶段-1-·-方法论" aria-label="Permalink to &quot;阶段 1 · 方法论&quot;">​</a></h2><p>建立系统设计的思考框架。</p><ul><li><strong>01 系统设计方法论</strong> - 设计流程、需求澄清、四步法</li><li><strong>02 容量估算</strong> - QPS/TPS、存储估算、带宽计算、缩放思维</li><li><strong>03 API 与数据流设计</strong> - API 设计、数据流图、状态机</li><li><strong>04 存储选型</strong> - 关系型/文档/键值/搜索/时序选型决策</li></ul><h2 id="阶段-2-·-基础组件" tabindex="-1">阶段 2 · 基础组件 <a class="header-anchor" href="#阶段-2-·-基础组件" aria-label="Permalink to &quot;阶段 2 · 基础组件&quot;">​</a></h2><p>掌握架构的积木。</p><ul><li><strong>05 负载均衡</strong> - L4/L7、算法、健康检查、会话保持</li><li><strong>06 消息队列</strong> - Kafka/RabbitMQ、生产消费模型、选型</li><li><strong>07 分布式缓存</strong> - Redis 集群、缓存策略、一致性</li><li><strong>08 数据库分片</strong> - 水平/垂直拆分、分片键、热点</li><li><strong>09 CDN 与边缘</strong> - CDN 原理、缓存、静态资源加速</li></ul><h2 id="阶段-3-·-高可用设计" tabindex="-1">阶段 3 · 高可用设计 <a class="header-anchor" href="#阶段-3-·-高可用设计" aria-label="Permalink to &quot;阶段 3 · 高可用设计&quot;">​</a></h2><p>让系统扛得住故障。</p><ul><li><strong>10 故障转移与冗余</strong> - 主备/双活、故障切换、多机房</li><li><strong>11 容灾与备份</strong> - RPO/RTO、备份策略、演练</li><li><strong>12 幂等与重试</strong> - 幂等键、重试策略、防重复</li><li><strong>13 限流与熔断</strong> - 令牌桶/漏桶、熔断降级、舱壁隔离</li><li><strong>14 监控与告警</strong> - 指标、日志、链路、告警设计</li></ul><h2 id="阶段-4-·-经典案例" tabindex="-1">阶段 4 · 经典案例 <a class="header-anchor" href="#阶段-4-·-经典案例" aria-label="Permalink to &quot;阶段 4 · 经典案例&quot;">​</a></h2><p>用真实场景演练设计。</p><ul><li><strong>15 短链系统</strong> - 哈希与 ID 生成、重定向、统计</li><li><strong>16 新闻信息流</strong> - 推拉模式、缓存、个性化</li><li><strong>17 聊天系统</strong> - WebSocket、消息存储、在线状态</li><li><strong>18 电商秒杀</strong> - 限流、库存扣减、防超卖</li><li><strong>19 搜索系统</strong> - 倒排索引、分词、相关性</li></ul><h2 id="阶段-5-·-资深架构" tabindex="-1">阶段 5 · 资深架构 <a class="header-anchor" href="#阶段-5-·-资深架构" aria-label="Permalink to &quot;阶段 5 · 资深架构&quot;">​</a></h2><p>进阶到架构师思维。</p><ul><li><strong>20 分布式事务</strong> - 2PC/Saga/TCC、最终一致性</li><li><strong>21 一致性协议</strong> - CAP、Raft、Paxos、ZooKeeper</li><li><strong>22 微服务拆分</strong> - 拆分原则、服务治理、容错</li><li><strong>23 事件驱动架构</strong> - 事件溯源、CQRS、消息编排</li><li><strong>24 大规模系统演进</strong> - 单体→微服务→中台演进路径</li><li><strong>25 成本与容量优化</strong> - 成本意识、容量规划、资源优化</li><li><strong>26 设计权衡与取舍</strong> - 一致性 vs 可用性、延迟 vs 成本</li></ul><h2 id="阶段-6-·-综合实战" tabindex="-1">阶段 6 · 综合实战 <a class="header-anchor" href="#阶段-6-·-综合实战" aria-label="Permalink to &quot;阶段 6 · 综合实战&quot;">​</a></h2><ul><li><strong>27 综合实战项目</strong> - 完整设计一个中大规模系统（含架构图、容量估算、高可用方案）</li></ul><hr><h2 id="概念依赖关系" tabindex="-1">概念依赖关系 <a class="header-anchor" href="#概念依赖关系" aria-label="Permalink to &quot;概念依赖关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01 -&gt; 02 -&gt; 03 -&gt; 04          (方法论)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        05 -&gt; 06 -&gt; ... -&gt; 09   (基础组件)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        10 -&gt; 11 -&gt; ... -&gt; 14   (高可用设计)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        15 -&gt; 16 -&gt; ... -&gt; 19   (经典案例,应用前面全部)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        20 -&gt; 21 -&gt; ... -&gt; 26   (资深架构)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>              27                (综合实战)</span></span></code></pre></div><h2 id="进度跟踪" tabindex="-1">进度跟踪 <a class="header-anchor" href="#进度跟踪" aria-label="Permalink to &quot;进度跟踪&quot;">​</a></h2><p>每完成一个概念,在 <code>progress.md</code> 更新状态:⬜ 未开始 / 🔄 学习中 / ✅ 已掌握。</p>`,29)])])}const u=a(r,[["render",e]]);export{c as __pageData,u as default};
